#[test]
#[cfg(all(
    unix,
    has_virtual_memory,
    not(feature = "transaction-mvcc"),
    not(feature = "transaction-cc-strict-2pl")
))]
fn single_version_tfunc_certification_prevents_write_skew() {
    use std::sync::Arc;
    use std::sync::mpsc;
    use std::time::Duration;

    clear_current_thread_transaction_for_test();
    let dir = tempfile::tempdir().unwrap();
    let runtime = TransactionRegionRuntime::create_file_backed_for_test(
        &dir.path().join("tmemory.bin"),
        &dir.path().join("tx-log.bin"),
        64,
    )
    .unwrap();
    let engine = crate::Engine::default();
    let module = transaction_test_module(
        &engine,
        r#"
            (module
              (import "host" "sync" (tfunc $sync))
              (tmemory 1)
              (tfunc (export "init")
                (i64.tstore (i32.const 0) (i64.const 1))
                (i64.tstore (i32.const 64) (i64.const 1)))
              (tfunc (export "write_skew_a")
                (local $b i64)
                (local.set $b (i64.tload (i32.const 64)))
                (tcall $sync)
                (if (i64.eq (local.get $b) (i64.const 1))
                  (then (i64.tstore (i32.const 0) (i64.const 0)))))
              (tfunc (export "write_skew_b")
                (local $a i64)
                (local.set $a (i64.tload (i32.const 0)))
                (tcall $sync)
                (if (i64.eq (local.get $a) (i64.const 1))
                  (then (i64.tstore (i32.const 64) (i64.const 0)))))
              (tfunc (export "read") (result i64 i64)
                (i64.tload (i32.const 0))
                (i64.tload (i32.const 64))))
        "#,
    );

    let mut init_linker = crate::Linker::new(&engine);
    init_linker.func_wrap("host", "sync", || Ok(())).unwrap();
    let mut init_store = crate::Store::new(&engine, ());
    init_store.set_transaction_region_runtime_for_test(runtime.clone());
    let init_instance = init_linker.instantiate(&mut init_store, &module).unwrap();
    init_instance
        .get_typed_func::<(), ()>(&mut init_store, "init")
        .unwrap()
        .call(&mut init_store, ())
        .unwrap();
    drop(init_store);

    let gate = Arc::new(super::region_runtime::TransactionTestGate::new(2));
    let make_store = |gate: Arc<super::region_runtime::TransactionTestGate>| {
        let mut linker = crate::Linker::new(&engine);
        linker
            .func_wrap("host", "sync", move || gate.wait())
            .unwrap();
        let mut store = crate::Store::new(&engine, ());
        store.set_transaction_region_runtime_for_test(runtime.clone());
        let instance = linker.instantiate(&mut store, &module).unwrap();
        (store, instance)
    };
    let (mut a_store, a_instance) = make_store(gate.clone());
    let write_a = a_instance
        .get_typed_func::<(), ()>(&mut a_store, "write_skew_a")
        .unwrap();
    let (mut b_store, b_instance) = make_store(gate.clone());
    let write_b = b_instance
        .get_typed_func::<(), ()>(&mut b_store, "write_skew_b")
        .unwrap();

    let (outcome_tx, outcome_rx) = mpsc::sync_channel(2);
    let a_outcome_tx = outcome_tx.clone();
    let a_writer = std::thread::spawn(move || {
        let _cleanup = clear_current_thread_transaction_on_drop_for_test();
        let result = write_a
            .call(&mut a_store, ())
            .map_err(|error| format!("{error:#}"));
        a_outcome_tx.send(result).unwrap();
    });
    let b_writer = std::thread::spawn(move || {
        let _cleanup = clear_current_thread_transaction_on_drop_for_test();
        let result = write_b
            .call(&mut b_store, ())
            .map_err(|error| format!("{error:#}"));
        outcome_tx.send(result).unwrap();
    });

    let reached = gate.wait_until_reached(Duration::from_secs(5)).unwrap();
    gate.release().unwrap();
    assert!(reached, "write-skew read gate did not reach both workers");
    let outcomes = [
        outcome_rx.recv_timeout(Duration::from_secs(5)).unwrap(),
        outcome_rx.recv_timeout(Duration::from_secs(5)).unwrap(),
    ];
    a_writer.join().unwrap();
    b_writer.join().unwrap();
    let conflict_count = outcomes.iter().filter(|outcome| outcome.is_err()).count();
    assert!(
        outcomes
            .iter()
            .filter_map(|outcome| outcome.as_ref().err())
            .all(|error| error.contains("transaction read conflict")
                || error.contains("transaction write conflict")),
        "unexpected write-skew outcomes: {outcomes:?}"
    );

    let mut read_linker = crate::Linker::new(&engine);
    read_linker.func_wrap("host", "sync", || Ok(())).unwrap();
    let mut read_store = crate::Store::new(&engine, ());
    read_store.set_transaction_region_runtime_for_test(runtime.clone());
    let read_instance = read_linker.instantiate(&mut read_store, &module).unwrap();
    let (a, b) = read_instance
        .get_typed_func::<(), (i64, i64)>(&mut read_store, "read")
        .unwrap()
        .call(&mut read_store, ())
        .unwrap();
    assert!(
        a + b >= 1,
        "single-version write skew violated A + B >= 1: A={a}, B={b}"
    );
    assert!(
        conflict_count >= 1,
        "write-skew schedule committed both transactions: {outcomes:?}"
    );
    single_version_certification_assert_runtime_quiescent(&runtime);
    clear_current_thread_transaction_for_test();
}

#[test]
#[cfg(all(
    unix,
    has_virtual_memory,
    not(feature = "transaction-mvcc"),
    not(feature = "transaction-cc-strict-2pl")
))]
fn single_version_tblock_commit_conflicts_route_all_exits_to_handler() {
    use std::sync::Arc;
    use std::sync::mpsc;
    use std::time::Duration;

    fn run(exit_name: &str, exit: &str) {
        clear_current_thread_transaction_for_test();
        let dir = tempfile::tempdir().unwrap();
        let runtime = TransactionRegionRuntime::create_file_backed_for_test(
            &dir.path().join("tmemory.bin"),
            &dir.path().join("tx-log.bin"),
            64,
        )
        .unwrap();
        let engine = crate::Engine::default();
        let module = transaction_test_module(
            &engine,
            &format!(
                r#"
                    (module
                      (import "host" "sync" (tfunc $sync))
                      (tmemory 1)
                      (func (export "conflict-a") (result i32)
                        (local $seen i64)
                        (tblock $done (result i32)
                          ((local.set $seen (i64.tload (i32.const 64)))
                           (tcall $sync)
                           (i64.tstore
                             (i32.const 0)
                             (i64.add (local.get $seen) (i64.const 1)))
                           {exit})
                          (else)))
                      (func (export "conflict-b") (result i32)
                        (local $seen i64)
                        (tblock $done (result i32)
                          ((local.set $seen (i64.tload (i32.const 0)))
                           (tcall $sync)
                           (i64.tstore
                             (i32.const 64)
                             (i64.add (local.get $seen) (i64.const 1)))
                           {exit})
                          (else))))
                "#,
            ),
        );

        let read_gate = Arc::new(super::region_runtime::TransactionTestGate::new(2));
        let second_exit_gate = Arc::new(super::region_runtime::TransactionTestGate::new(1));

        let mut first_linker = crate::Linker::new(&engine);
        let first_read_gate = read_gate.clone();
        first_linker
            .func_wrap("host", "sync", move || first_read_gate.wait())
            .unwrap();
        let mut first_store = crate::Store::new(&engine, ());
        first_store.set_transaction_region_runtime_for_test(runtime.clone());
        let first_instance = first_linker.instantiate(&mut first_store, &module).unwrap();
        let first = first_instance
            .get_typed_func::<(), i32>(&mut first_store, "conflict-a")
            .unwrap();

        let mut second_linker = crate::Linker::new(&engine);
        let second_read_gate = read_gate.clone();
        let second_worker_exit_gate = second_exit_gate.clone();
        second_linker
            .func_wrap("host", "sync", move || {
                second_read_gate.wait()?;
                second_worker_exit_gate.wait()
            })
            .unwrap();
        let mut second_store = crate::Store::new(&engine, ());
        second_store.set_transaction_region_runtime_for_test(runtime.clone());
        let second_instance = second_linker
            .instantiate(&mut second_store, &module)
            .unwrap();
        let second = second_instance
            .get_typed_func::<(), i32>(&mut second_store, "conflict-b")
            .unwrap();

        let (outcome_tx, outcome_rx) = mpsc::sync_channel(2);
        let first_outcome_tx = outcome_tx.clone();
        let first_worker = std::thread::spawn(move || {
            let _cleanup = clear_current_thread_transaction_on_drop_for_test();
            first_outcome_tx
                .send(
                    first
                        .call(&mut first_store, ())
                        .map_err(|error| format!("{error:#}")),
                )
                .unwrap();
        });
        let second_worker = std::thread::spawn(move || {
            let _cleanup = clear_current_thread_transaction_on_drop_for_test();
            outcome_tx
                .send(
                    second
                        .call(&mut second_store, ())
                        .map_err(|error| format!("{error:#}")),
                )
                .unwrap();
        });

        assert!(
            read_gate
                .wait_until_reached(Duration::from_secs(5))
                .unwrap(),
            "{exit_name}: tblock conflict gate did not reach both workers"
        );
        read_gate.release().unwrap();
        let first_outcome = outcome_rx.recv_timeout(Duration::from_secs(5)).unwrap();
        assert_eq!(first_outcome, Ok(1), "{exit_name}");
        assert!(
            second_exit_gate
                .wait_until_reached(Duration::from_secs(5))
                .unwrap(),
            "{exit_name}: second tblock worker did not reach its exit gate"
        );
        second_exit_gate.release().unwrap();
        let second_outcome = outcome_rx.recv_timeout(Duration::from_secs(5)).unwrap();
        first_worker.join().unwrap();
        second_worker.join().unwrap();

        assert_eq!(
            second_outcome,
            Ok(0),
            "{exit_name}: tblock commit conflict trapped instead of running its handler"
        );
        single_version_certification_assert_runtime_quiescent(&runtime);
        clear_current_thread_transaction_for_test();
    }

    for (exit_name, exit) in [
        ("fallthrough", "(i32.const 1)"),
        ("br", "(i32.const 1) (br $done)"),
        (
            "br_if",
            "(i32.const 1) (i32.const 1) (br_if $done) (unreachable)",
        ),
        ("br_table", "(i32.const 1) (i32.const 0) (br_table $done)"),
        ("return", "(i32.const 1) (return)"),
    ] {
        run(exit_name, exit);
    }
}

