#[test]
#[cfg(all(
    unix,
    has_virtual_memory,
    feature = "transaction-cc-optimistic-validation",
    not(feature = "transaction-mvcc")
))]
fn optimistic_validation_disjoint_tfunc_commits_overlap_certification() {
    use std::sync::Arc;
    use std::time::Duration;

    clear_current_thread_transaction_for_test();
    let dir = tempfile::tempdir().unwrap();
    let runtime = TransactionRegionRuntime::create_file_backed_for_test(
        &dir.path().join("tmemory.bin"),
        &dir.path().join("tx-log.bin"),
        64,
    )
    .unwrap();
    let engine = crate::Engine::default();
    let module = transaction_test_module(
        &engine,
        r#"
            (module
              (tmemory 1)
              (tfunc (export "write_a")
                (i64.tstore (i32.const 0) (i64.const 11)))
              (tfunc (export "write_b")
                (i64.tstore (i32.const 64) (i64.const 22))))
        "#,
    );

    let mut a_store = crate::Store::new(&engine, ());
    a_store.set_transaction_region_runtime_for_test(runtime.clone());
    let a_instance = crate::Instance::new(&mut a_store, &module, &[]).unwrap();
    let write_a = a_instance
        .get_typed_func::<(), ()>(&mut a_store, "write_a")
        .unwrap();
    let mut b_store = crate::Store::new(&engine, ());
    b_store.set_transaction_region_runtime_for_test(runtime.clone());
    let b_instance = crate::Instance::new(&mut b_store, &module, &[]).unwrap();
    let write_b = b_instance
        .get_typed_func::<(), ()>(&mut b_store, "write_b")
        .unwrap();

    let gate = Arc::new(super::region_runtime::TransactionTestGate::new(2));
    runtime
        .set_optimistic_certification_gate_for_test(Some(gate.clone()))
        .unwrap();
    let a_writer = std::thread::spawn(move || {
        let _cleanup = clear_current_thread_transaction_on_drop_for_test();
        write_a
            .call(&mut a_store, ())
            .map_err(|error| format!("{error:#}"))
    });
    let b_writer = std::thread::spawn(move || {
        let _cleanup = clear_current_thread_transaction_on_drop_for_test();
        write_b
            .call(&mut b_store, ())
            .map_err(|error| format!("{error:#}"))
    });

    let reached = gate.wait_until_reached(Duration::from_secs(5)).unwrap();
    if !reached {
        gate.release().unwrap();
        let outcomes = [a_writer.join().unwrap(), b_writer.join().unwrap()];
        panic!("disjoint commits did not both reach certification: {outcomes:?}");
    }
    assert_eq!(
        runtime.optimistic_certification_counts_for_test().unwrap(),
        (2, 2)
    );
    gate.release().unwrap();
    let outcomes = [a_writer.join().unwrap(), b_writer.join().unwrap()];
    runtime
        .set_optimistic_certification_gate_for_test(None)
        .unwrap();

    assert!(
        outcomes.iter().all(std::result::Result::is_ok),
        "disjoint certified commits conflicted: {outcomes:?}"
    );
    assert_eq!(
        runtime.optimistic_certification_counts_for_test().unwrap(),
        (2, 0)
    );
    single_version_certification_assert_runtime_quiescent(&runtime);
    clear_current_thread_transaction_for_test();
}

#[test]
#[cfg(all(
    feature = "transaction-cc-optimistic-validation",
    not(feature = "transaction-mvcc")
))]
fn optimistic_validation_certification_version_mismatch_cleans_lifecycle() -> Result<()> {
    clear_current_thread_transaction_for_test();
    let runtime = TransactionRegionRuntime::new_for_test();
    let mut state = TransactionState::default();
    let transaction = state.begin_with_region_runtime(&runtime)?;
    let granule = GranuleId::TMemory {
        instance: None,
        memory_index: 0,
        granule_index: 7,
    };
    state.acquire_granule_read(granule, 0)?;
    let certification = state.acquire_active_optimistic_certification()?;
    assert_eq!(runtime.optimistic_certification_counts_for_test()?, (1, 1));

    runtime.bump_versioned_granules([granule])?;
    let error = state.validate_active_read(granule, 0).unwrap_err();
    assert!(
        error.to_string().contains("transaction read conflict"),
        "{error:?}"
    );
    assert!(!runtime.transaction_is_terminal_commit_for_test(transaction)?);
    state.abort()?;
    drop(certification);

    assert!(state.active_transaction().is_none());
    assert!(state.selected_visibility.is_none());
    assert!(state.visibility_snapshot.is_none());
    assert!(state.suspended.is_empty());
    assert!(!state.terminal_commit_active);
    assert_eq!(runtime.optimistic_certification_counts_for_test()?, (1, 0));
    single_version_certification_assert_runtime_quiescent(&runtime);
    clear_current_thread_transaction_for_test();
    Ok(())
}

#[cfg(all(unix, has_virtual_memory, feature = "transaction-mvcc"))]
fn mvcc_serializable_shared_memory_module(engine: &crate::Engine) -> crate::Module {
    transaction_test_module(
        engine,
        r#"
            (module
              (import "host" "sync" (func $sync))
              (tmemory 1)
              (tfunc (export "init") (param i32 i32 i32)
                (i32.tstore (i32.const 0) (local.get 0))
                (i32.tstore (i32.const 64) (local.get 1))
                (i32.tstore (i32.const 128) (local.get 2)))
              (tfunc (export "blind_a") (param i32)
                (i32.tstore (i32.const 0) (local.get 0))
                (call $sync))
              (tfunc (export "increment_a")
                (local $old i32)
                (local.set $old (i32.tload (i32.const 0)))
                (i32.tstore
                  (i32.const 0)
                  (i32.add (local.get $old) (i32.const 1)))
                (call $sync))
              (tfunc (export "read_a_write_b") (param i32)
                (drop (i32.tload (i32.const 0)))
                (i32.tstore (i32.const 64) (local.get 0))
                (call $sync))
              (tfunc (export "write_a") (param i32)
                (call $sync)
                (i32.tstore (i32.const 0) (local.get 0)))
              (tfunc (export "write_b") (param i32)
                (call $sync)
                (i32.tstore (i32.const 64) (local.get 0)))
              (tfunc (export "write_skew_a")
                (local $a i32)
                (local $b i32)
                (local.set $a (i32.tload (i32.const 0)))
                (local.set $b (i32.tload (i32.const 64)))
                (if (i32.and
                      (i32.eq (local.get $a) (i32.const 1))
                      (i32.eq (local.get $b) (i32.const 1)))
                  (then (i32.tstore (i32.const 0) (i32.const 0))))
                (call $sync))
              (tfunc (export "write_skew_b")
                (local $a i32)
                (local $b i32)
                (local.set $a (i32.tload (i32.const 0)))
                (local.set $b (i32.tload (i32.const 64)))
                (if (i32.and
                      (i32.eq (local.get $a) (i32.const 1))
                      (i32.eq (local.get $b) (i32.const 1)))
                  (then (i32.tstore (i32.const 64) (i32.const 0))))
                (call $sync))
              (tfunc (export "read_a_twice") (result i32 i32)
                (local $first i32)
                (local.set $first (i32.tload (i32.const 0)))
                (call $sync)
                (local.get $first)
                (i32.tload (i32.const 0)))
              (tfunc (export "read") (result i32 i32 i32)
                (i32.tload (i32.const 0))
                (i32.tload (i32.const 64))
                (i32.tload (i32.const 128))))
        "#,
    )
}

#[cfg(all(unix, has_virtual_memory, feature = "transaction-mvcc"))]
fn mvcc_serializable_shared_memory_store(
    engine: &crate::Engine,
    module: &crate::Module,
    runtime: &TransactionRegionRuntime,
    sync: Arc<dyn Fn() -> Result<()> + Send + Sync>,
) -> (crate::Store<()>, crate::Instance) {
    mvcc_serializable_shared_memory_store_after_dummies(engine, module, runtime, sync, 0)
}

#[cfg(all(unix, has_virtual_memory, feature = "transaction-mvcc"))]
fn mvcc_serializable_shared_memory_store_after_dummies(
    engine: &crate::Engine,
    module: &crate::Module,
    runtime: &TransactionRegionRuntime,
    sync: Arc<dyn Fn() -> Result<()> + Send + Sync>,
    dummy_instances: usize,
) -> (crate::Store<()>, crate::Instance) {
    let mut linker = crate::Linker::new(engine);
    linker.func_wrap("host", "sync", move || sync()).unwrap();
    let mut store = crate::Store::new(engine, ());
    store.set_transaction_region_runtime_for_test(runtime.clone());
    let dummy = transaction_test_module(engine, "(module)");
    for _ in 0..dummy_instances {
        crate::Instance::new(&mut store, &dummy, &[]).unwrap();
    }
    let instance = linker.instantiate(&mut store, module).unwrap();
    (store, instance)
}

#[cfg(feature = "transaction-mvcc")]
fn mvcc_serializable_assert_one_commit_one_conflict(outcomes: &[std::result::Result<(), String>]) {
    assert_eq!(outcomes.iter().filter(|outcome| outcome.is_ok()).count(), 1);
    let conflicts = outcomes
        .iter()
        .filter_map(|outcome| outcome.as_ref().err())
        .collect::<Vec<_>>();
    assert_eq!(conflicts.len(), 1);
    assert!(
        conflicts[0].contains("transaction MVCC certification conflict")
            || conflicts[0].contains("transaction read conflict")
            || conflicts[0].contains("transaction write conflict")
            || conflicts[0].contains("transaction conflict would wait")
            || conflicts[0].contains("transaction was conflict-aborted by another transaction"),
        "unexpected serializable MVCC conflict: {}",
        conflicts[0]
    );
}

#[cfg(feature = "transaction-mvcc")]
fn mvcc_serializable_assert_runtime_quiescent(runtime: &TransactionRegionRuntime) {
    let visibility = runtime.visibility_for_test();
    assert_eq!(runtime.mvcc_certification_counts_for_test().unwrap().1, 0);
    let (active, begun, finished, dropped) =
        visibility.snapshot_lifecycle_counts_for_test().unwrap();
    assert_eq!(active, 0);
    assert_eq!(begun, finished + dropped);
    let (registered, published, aborted) = visibility
        .runtime()
        .commit_lifecycle_counts_for_test()
        .unwrap();
    assert_eq!(registered, published + aborted);
    drop(visibility.begin_gc_barrier_for_test().unwrap());
    drop(runtime.begin_persistent_gc_for_test().unwrap());
}

#[cfg(feature = "transaction-mvcc")]
fn mvcc_serializable_release_gate_after_reached(
    gate: &MvccCommitTestHook,
    participants: usize,
    description: &str,
) {
    use std::time::Duration;

    let reached = gate.wait_until_reached(Duration::from_secs(5));
    gate.release();
    assert!(
        reached,
        "{description} did not reach all {participants} participants"
    );
}

#[test]
#[cfg(all(unix, has_virtual_memory, feature = "transaction-mvcc"))]
fn mvcc_serializable_write_skew_aborts_one_writer() {
    use std::sync::Arc;
    use std::sync::mpsc;
    use std::time::Duration;

    clear_current_thread_transaction_for_test();
    let dir = tempfile::tempdir().unwrap();
    let runtime = TransactionRegionRuntime::create_file_backed_for_test(
        &dir.path().join("tmemory.bin"),
        &dir.path().join("tx-log.bin"),
        64,
    )
    .unwrap();
    let engine = crate::Engine::default();
    let module = mvcc_serializable_shared_memory_module(&engine);
    let (mut init_store, init_instance) =
        mvcc_serializable_shared_memory_store(&engine, &module, &runtime, Arc::new(|| Ok(())));
    init_instance
        .get_typed_func::<(i32, i32, i32), ()>(&mut init_store, "init")
        .unwrap()
        .call(&mut init_store, (1, 1, 0))
        .unwrap();
    drop(init_store);

    let commit_gate = Arc::new(MvccCommitTestHook::new(2));
    let a_gate = commit_gate.clone();
    let (mut a_store, a_instance) = mvcc_serializable_shared_memory_store(
        &engine,
        &module,
        &runtime,
        Arc::new(move || a_gate.wait()),
    );
    let a_owner = a_instance.id().as_u32();
    let write_a = a_instance
        .get_typed_func::<(), ()>(&mut a_store, "write_skew_a")
        .unwrap();
    let (outcome_tx, outcome_rx) = mpsc::sync_channel(2);
    let a_outcome_tx = outcome_tx.clone();
    let a_writer = std::thread::spawn(move || {
        let _cleanup = clear_current_thread_transaction_on_drop_for_test();
        let result = write_a
            .call(&mut a_store, ())
            .map_err(|error| format!("{error:#}"));
        a_outcome_tx.send(result).unwrap();
    });
    let (mut b_store, b_instance) = mvcc_serializable_shared_memory_store_after_dummies(
        &engine,
        &module,
        &runtime,
        Arc::new({
            let commit_gate = commit_gate.clone();
            move || commit_gate.wait()
        }),
        1,
    );
    let b_owner = b_instance.id().as_u32();
    assert_ne!(
        a_owner, b_owner,
        "shared file-backed conflicts must not depend on equal store-local instance ids"
    );
    let write_b = b_instance
        .get_typed_func::<(), ()>(&mut b_store, "write_skew_b")
        .unwrap();
    let b_outcome_tx = outcome_tx;
    let b_writer = std::thread::spawn(move || {
        let _cleanup = clear_current_thread_transaction_on_drop_for_test();
        let result = write_b
            .call(&mut b_store, ())
            .map_err(|error| format!("{error:#}"));
        b_outcome_tx.send(result).unwrap();
    });

    mvcc_serializable_release_gate_after_reached(&commit_gate, 2, "write-skew staging gate");
    let outcomes = [
        outcome_rx.recv_timeout(Duration::from_secs(5)).unwrap(),
        outcome_rx.recv_timeout(Duration::from_secs(5)).unwrap(),
    ];
    a_writer.join().unwrap();
    b_writer.join().unwrap();
    mvcc_serializable_assert_one_commit_one_conflict(&outcomes);

    let (mut read_store, read_instance) =
        mvcc_serializable_shared_memory_store(&engine, &module, &runtime, Arc::new(|| Ok(())));
    let (a, b, _) = read_instance
        .get_typed_func::<(), (i32, i32, i32)>(&mut read_store, "read")
        .unwrap()
        .call(&mut read_store, ())
        .unwrap();
    assert!(a + b >= 1, "write skew violated A + B >= 1: A={a}, B={b}");
    mvcc_serializable_assert_runtime_quiescent(&runtime);
    clear_current_thread_transaction_for_test();
}

#[test]
#[cfg(all(unix, has_virtual_memory, feature = "transaction-mvcc"))]
fn mvcc_serializable_blind_write_write_aborts_one_writer() {
    use std::sync::Arc;
    use std::sync::mpsc;
    use std::time::Duration;

    clear_current_thread_transaction_for_test();
    let dir = tempfile::tempdir().unwrap();
    let runtime = TransactionRegionRuntime::create_file_backed_for_test(
        &dir.path().join("tmemory.bin"),
        &dir.path().join("tx-log.bin"),
        64,
    )
    .unwrap();
    let engine = crate::Engine::default();
    let module = mvcc_serializable_shared_memory_module(&engine);
    let (mut init_store, init_instance) =
        mvcc_serializable_shared_memory_store(&engine, &module, &runtime, Arc::new(|| Ok(())));
    init_instance
        .get_typed_func::<(i32, i32, i32), ()>(&mut init_store, "init")
        .unwrap()
        .call(&mut init_store, (1, 0, 0))
        .unwrap();
    drop(init_store);

    let ready = Arc::new(MvccCommitTestHook::new(2));
    let (outcome_tx, outcome_rx) = mpsc::sync_channel(2);
    let mut writers = Vec::new();
    let mut owners = Vec::new();
    for (dummy_instances, value) in [2, 3].into_iter().enumerate() {
        let thread_ready = ready.clone();
        let (mut store, instance) = mvcc_serializable_shared_memory_store_after_dummies(
            &engine,
            &module,
            &runtime,
            Arc::new(move || thread_ready.wait()),
            dummy_instances,
        );
        owners.push(instance.id().as_u32());
        let write = instance
            .get_typed_func::<i32, ()>(&mut store, "blind_a")
            .unwrap();
        let outcome_tx = outcome_tx.clone();
        writers.push(std::thread::spawn(move || {
            let _cleanup = clear_current_thread_transaction_on_drop_for_test();
            outcome_tx
                .send(
                    write
                        .call(&mut store, value)
                        .map_err(|error| format!("{error:#}")),
                )
                .unwrap();
        }));
    }
    assert_ne!(
        owners[0], owners[1],
        "shared file-backed conflicts must not depend on equal store-local instance ids"
    );
    drop(outcome_tx);
    mvcc_serializable_release_gate_after_reached(&ready, 2, "blind-write staging gate");
    let outcomes = [
        outcome_rx.recv_timeout(Duration::from_secs(5)).unwrap(),
        outcome_rx.recv_timeout(Duration::from_secs(5)).unwrap(),
    ];
    for writer in writers {
        writer.join().unwrap();
    }
    mvcc_serializable_assert_one_commit_one_conflict(&outcomes);

    let (mut read_store, read_instance) =
        mvcc_serializable_shared_memory_store(&engine, &module, &runtime, Arc::new(|| Ok(())));
    let (a, _, _) = read_instance
        .get_typed_func::<(), (i32, i32, i32)>(&mut read_store, "read")
        .unwrap()
        .call(&mut read_store, ())
        .unwrap();
    assert!(matches!(a, 2 | 3));
    mvcc_serializable_assert_runtime_quiescent(&runtime);
    clear_current_thread_transaction_for_test();
}

