#[test]
#[cfg(all(
    unix,
    has_virtual_memory,
    feature = "transaction-mvcc",
    feature = "transaction-cc-optimistic-validation"
))]
fn mvcc_object_shared_install_rejects_local_update_and_refreshes_newer_directory() -> Result<()> {
    let temp = tempfile::tempdir()?;
    let runtime = TransactionRegionRuntime::new_for_test();
    let mut objects = ObjectTable::default();
    objects.set_shared_region_runtime(Some(runtime.clone()));
    let object_id = objects.allocate_payload_with_persistence(
        ObjectPayload::Struct(vec![ObjectValue::I32(1)]),
        true,
    )?;
    let first =
        mvcc_object_mapped_directory_entry(&temp.path().join("first.bin"), object_id, 1, 11)?;
    let first = runtime
        .install_persistent_object_directory_entries([first])?
        .pop()
        .context("first shared object entry was not installed")?;
    objects.install_persistent_object_directory_entry(first)?;
    let stale_version = objects.version(object_id)?;

    let error = objects
        .install_current_payload_snapshot(
            object_id,
            &ObjectPayload::Struct(vec![ObjectValue::I32(99)]),
        )
        .unwrap_err();
    assert!(
        error
            .to_string()
            .contains("shared persistent object current payload"),
        "{error:?}"
    );
    assert_eq!(objects.version(object_id)?, stale_version);

    let second =
        mvcc_object_mapped_directory_entry(&temp.path().join("second.bin"), object_id, 2, 22)?;
    runtime.install_persistent_object_directory_entries([second])?;
    assert_eq!(
        objects.current_payload_snapshot(object_id)?,
        Some(ObjectPayload::Struct(vec![ObjectValue::I32(22)]))
    );
    assert!(objects.version(object_id)? > stale_version);
    Ok(())
}

#[test]
#[cfg(feature = "transaction-mvcc")]
fn mvcc_commit_prepare_transaction_local_promotion_is_pending_only() {
    clear_current_thread_transaction_for_test();
    let runtime = TransactionRegionRuntime::new_for_test();
    let visibility = runtime.visibility_for_test();
    let mut state = TransactionState::default();
    let mut objects = ObjectTable::default();
    state.begin_with_region_runtime(&runtime).unwrap();
    let local = state
        .allocate_transaction_local_struct(vec![ObjectValue::I32(7)], None)
        .unwrap();

    let promoted = state
        .promote_transaction_object_graph_for_test(&mut objects, local)
        .unwrap();
    let payload = state
        .staged_object_payload_for_test(promoted)
        .unwrap()
        .clone();
    let commit = Arc::new(CommitRecord::pending());
    mvcc_object_prepare_promoted_payloads(
        visibility.runtime(),
        commit.clone(),
        &[(promoted, payload)],
    );

    assert_eq!(
        visibility.runtime().object_chain_count_for_test().unwrap(),
        1
    );
    assert_eq!(
        visibility
            .runtime()
            .object_version_count_for_test(promoted)
            .unwrap(),
        1
    );
    assert_eq!(
        visibility
            .runtime()
            .read_object(100, promoted, || panic!("promotion chain must exist"))
            .unwrap(),
        None
    );
    assert_eq!(
        visibility
            .runtime()
            .abort_prepared_object_promotions_for_test(&commit)
            .unwrap(),
        1
    );
    state.abort_allocated_objects(&mut objects).unwrap();
    clear_current_thread_transaction_for_test();
}

#[test]
#[cfg(feature = "transaction-mvcc")]
fn mvcc_commit_prepare_transaction_local_promotions_share_one_record() {
    clear_current_thread_transaction_for_test();
    let runtime = TransactionRegionRuntime::new_for_test();
    let visibility = runtime.visibility_for_test();
    let mut state = TransactionState::default();
    let mut objects = ObjectTable::default();
    state.begin_with_region_runtime(&runtime).unwrap();
    let local_struct = state
        .allocate_transaction_local_struct(vec![ObjectValue::I32(7)], None)
        .unwrap();
    let local_array = state
        .allocate_transaction_local_array(vec![ObjectValue::I32(8)], None)
        .unwrap();
    let promoted_struct = state
        .promote_transaction_object_graph_for_test(&mut objects, local_struct)
        .unwrap();
    let promoted_array = state
        .promote_transaction_object_graph_for_test(&mut objects, local_array)
        .unwrap();
    let struct_payload = state
        .staged_object_payload_for_test(promoted_struct)
        .unwrap()
        .clone();
    let array_payload = state
        .staged_object_payload_for_test(promoted_array)
        .unwrap()
        .clone();
    let commit = Arc::new(CommitRecord::pending());
    mvcc_object_prepare_promoted_payloads(
        visibility.runtime(),
        commit.clone(),
        &[
            (promoted_struct, struct_payload),
            (promoted_array, array_payload),
        ],
    );

    let struct_record = visibility
        .runtime()
        .object_newest_commit_record_for_test(promoted_struct)
        .unwrap();
    let array_record = visibility
        .runtime()
        .object_newest_commit_record_for_test(promoted_array)
        .unwrap();
    assert!(Arc::ptr_eq(struct_record.as_ref().unwrap(), &commit));
    assert!(Arc::ptr_eq(array_record.as_ref().unwrap(), &commit));
    assert!(Arc::ptr_eq(
        struct_record.as_ref().unwrap(),
        array_record.as_ref().unwrap()
    ));

    assert_eq!(
        visibility
            .runtime()
            .abort_prepared_object_promotions_for_test(&commit)
            .unwrap(),
        2
    );
    state.abort_allocated_objects(&mut objects).unwrap();

    assert_eq!(
        visibility.runtime().object_chain_count_for_test().unwrap(),
        0
    );
    assert_eq!(
        visibility
            .runtime()
            .object_version_count_for_test(promoted_struct)
            .unwrap(),
        0
    );
    assert_eq!(
        visibility
            .runtime()
            .object_version_count_for_test(promoted_array)
            .unwrap(),
        0
    );
    assert!(objects.live_slot(promoted_struct).is_err());
    assert!(objects.live_slot(promoted_array).is_err());
    assert_eq!(objects.live_count(), 0);
    assert_eq!(state.allocated_object_count_for_test(), 0);
    clear_current_thread_transaction_for_test();
}

#[test]
#[cfg(feature = "transaction-mvcc")]
fn mvcc_object_gc_traces_only_current_object_table_payloads() {
    let runtime = MvccRuntime::default();
    let mut objects = ObjectTable::default();
    let historical_child = objects
        .allocate_payload_with_persistence(ObjectPayload::Struct(vec![ObjectValue::I32(1)]), true)
        .unwrap();
    let baseline = ObjectPayload::Struct(vec![ObjectValue::Ref(Some(historical_child))]);
    let current = ObjectPayload::Struct(vec![ObjectValue::Ref(None)]);
    let root = objects
        .allocate_payload_with_persistence(baseline.clone(), true)
        .unwrap();

    mvcc_object_install_committed_payload(&runtime, &mut objects, root, Some(baseline), current, 1);
    let report = objects
        .persistent_mark_sweep_from_roots_uncoordinated_for_test([root])
        .unwrap();

    assert_eq!(runtime.object_chain_count_for_test().unwrap(), 1);
    assert_eq!(runtime.object_version_count_for_test(root).unwrap(), 2);
    assert!(report.mark.reachable.contains(&root));
    assert!(
        report
            .mark
            .unreachable_persistent
            .contains(&historical_child)
    );
    assert!(objects.live_slot(historical_child).is_err());
}

#[test]
#[cfg(all(
    unix,
    has_virtual_memory,
    feature = "transaction-mvcc",
    feature = "transaction-cc-optimistic-validation"
))]
fn mvcc_object_current_snapshot_refreshes_shared_directory() -> Result<()> {
    let runtime = TransactionRegionRuntime::new_for_test();
    let temp = tempfile::tempdir()?;
    let path = temp.path().join("region.bin");
    let mut region =
        crate::runtime::vm::block_region::FileBackedMemoryBlockRegion::create_for_test(&path, 8)?;
    let object_id = ObjectId { object_index: 41 };
    crate::runtime::vm::block_region::publish_committed_struct_object(
        &path,
        7,
        object_id.object_index,
        1,
        TypeLayoutId::DEFAULT_STRUCT.get(),
        &[7],
    )?;
    region.refresh_from_image()?;
    let recovered =
        crate::runtime::vm::block_region::reopen_and_recover_file_backed_region_for_runtime(&path)?;
    let winner = recovered
        .committed_object_winners()?
        .into_iter()
        .find(|winner| winner.object_id == object_id.object_index)
        .context("missing shared-directory object winner")?;
    runtime.install_persistent_object_directory_entries([PersistentObjectDirectoryEntry {
        object_id,
        kind: ObjectKind::Struct,
        directory_version: 0,
        record_version: winner.version,
        type_layout_id: winner.type_layout_id,
        runtime_type_index: None,
        record_source: Some(PersistentObjectRecordSource {
            mapped_source: recovered_mapped_source_for_test(&recovered),
            location: PersistentObjectRecordLocation {
                data_block: winner.data_block,
                data_offset: winner.data_offset,
                data_record_offset: u64::try_from(winner.data_record_offset)?,
                record_len: winner.record_len,
            },
        }),
    }])?;
    let mut objects = ObjectTable::default();
    objects.set_shared_region_runtime(Some(runtime));

    assert!(objects.live_slot(object_id).is_err());
    assert_eq!(
        objects.current_payload_snapshot(object_id)?,
        Some(ObjectPayload::Struct(vec![ObjectValue::I32(7)]))
    );
    assert_eq!(objects.live_count(), 1);
    assert!(objects.current_record_is_persistent_mapped_for_test(object_id)?);
    Ok(())
}

#[test]
#[cfg(feature = "transaction-mvcc")]
fn mvcc_visibility_repeated_tmemory_loads_remain_stable() {
    use crate::AsContextMut;
    use core::sync::atomic::{AtomicU32, Ordering};

    let engine = crate::Engine::default();
    let module = transaction_test_module(
        &engine,
        r#"
            (module
              (import "host" "advance" (func $advance))
              (tmemory $m (export "memory") 1)
              (func (export "read_twice") (result i32 i32)
                (local $first i32)
                (local.set $first (i32.tload $m (i32.const 0)))
                (call $advance)
                (local.get $first)
                (i32.tload $m (i32.const 0))))
        "#,
    );
    let runtime = TransactionRegionRuntime::new_for_test();
    let visibility = runtime.visibility_for_test();
    let instance_id = Arc::new(AtomicU32::new(u32::MAX));
    let host_instance_id = Arc::clone(&instance_id);
    let host_visibility = visibility.clone();
    let mut store = crate::Store::new(&engine, ());
    store.set_transaction_region_runtime_for_test(runtime.clone());
    let mut linker = crate::Linker::new(&engine);
    linker
        .func_wrap(
            "host",
            "advance",
            move |caller: crate::Caller<'_, ()>| -> Result<()> {
                let owner = host_instance_id.load(Ordering::SeqCst);
                let granule = GranuleId::TMemory {
                    instance: Some(owner),
                    memory_index: 0,
                    granule_index: 0,
                };
                let mut baseline = vec![0; TMEMORY_GRANULE_SIZE];
                baseline[..4].copy_from_slice(&11_i32.to_le_bytes());
                let mut current = baseline.clone();
                current[..4].copy_from_slice(&22_i32.to_le_bytes());
                let commit = Arc::new(CommitRecord::pending());
                let mut prepare = host_visibility.runtime().begin_prepare(commit.clone())?;
                prepare.prepare_memory(granule, || Ok(baseline), current.clone())?;
                drop(prepare);
                commit.commit(1)?;

                caller
                    .store
                    .0
                    .instance_mut(InstanceId::from_u32(owner))
                    .get_tmemory_mut(wasmtime_environ::TMemoryIndex::from_u32(0))
                    .context("missing transactional memory sidecar")?
                    .commit_range(0, &current[..4])?;
                Ok(())
            },
        )
        .unwrap();
    let instance = linker.instantiate(&mut store, &module).unwrap();
    instance_id.store(instance.id().as_u32(), Ordering::SeqCst);
    store
        .as_context_mut()
        .0
        .instance_mut(instance.id())
        .get_tmemory_mut(wasmtime_environ::TMemoryIndex::from_u32(0))
        .unwrap()
        .commit_range(0, &11_i32.to_le_bytes())
        .unwrap();
    let read_twice = instance
        .get_typed_func::<(), (i32, i32)>(&mut store, "read_twice")
        .unwrap();

    store
        .transaction_state_mut()
        .begin_with_region_runtime(&runtime)
        .unwrap();
    assert_eq!(read_twice.call(&mut store, ()).unwrap(), (11, 11));
    store.transaction_state_mut().abort().unwrap();
}

#[test]
#[cfg(feature = "transaction-mvcc")]
fn mvcc_visibility_partial_and_cross_granule_tmemory_stores_use_one_snapshot() {
    use crate::AsContextMut;
    use core::sync::atomic::{AtomicU32, Ordering};

    let engine = crate::Engine::default();
    let module = transaction_test_module(
        &engine,
        r#"
            (module
              (import "host" "advance" (func $advance))
              (tmemory $m 1)
              (func (export "store_and_read") (result i64)
                (call $advance)
                (i32.tstore $m (i32.const 62) (i32.const 0x44332211))
                (i64.tload $m (i32.const 60))))
        "#,
    );
    let runtime = TransactionRegionRuntime::new_for_test();
    let visibility = runtime.visibility_for_test();
    let instance_id = Arc::new(AtomicU32::new(u32::MAX));
    let host_instance_id = Arc::clone(&instance_id);
    let host_visibility = visibility.clone();
    let mut store = crate::Store::new(&engine, ());
    store.set_transaction_region_runtime_for_test(runtime.clone());
    let mut linker = crate::Linker::new(&engine);
    linker
        .func_wrap(
            "host",
            "advance",
            move |caller: crate::Caller<'_, ()>| -> Result<()> {
                let owner = host_instance_id.load(Ordering::SeqCst);
                let mut old0 = vec![0xa0; TMEMORY_GRANULE_SIZE];
                let mut old1 = vec![0xa1; TMEMORY_GRANULE_SIZE];
                old0[60..].copy_from_slice(&[0x10, 0x11, 0x12, 0x13]);
                old1[..4].copy_from_slice(&[0x14, 0x15, 0x16, 0x17]);
                let mut new0 = vec![0xb0; TMEMORY_GRANULE_SIZE];
                let mut new1 = vec![0xb1; TMEMORY_GRANULE_SIZE];
                new0[60..].copy_from_slice(&[0x20, 0x21, 0x22, 0x23]);
                new1[..4].copy_from_slice(&[0x24, 0x25, 0x26, 0x27]);
                let commit = Arc::new(CommitRecord::pending());
                let mut prepare = host_visibility.runtime().begin_prepare(commit.clone())?;
                prepare.prepare_memory(
                    GranuleId::TMemory {
                        instance: Some(owner),
                        memory_index: 0,
                        granule_index: 0,
                    },
                    || Ok(old0),
                    new0.clone(),
                )?;
                prepare.prepare_memory(
                    GranuleId::TMemory {
                        instance: Some(owner),
                        memory_index: 0,
                        granule_index: 1,
                    },
                    || Ok(old1),
                    new1.clone(),
                )?;
                drop(prepare);
                commit.commit(1)?;

                let mut instance = caller.store.0.instance_mut(InstanceId::from_u32(owner));
                let tmemory = instance
                    .as_mut()
                    .get_tmemory_mut(wasmtime_environ::TMemoryIndex::from_u32(0))
                    .context("missing transactional memory sidecar")?;
                tmemory.commit_range(0, &new0)?;
                tmemory.commit_range(TMEMORY_GRANULE_SIZE, &new1)?;
                Ok(())
            },
        )
        .unwrap();
    let instance = linker.instantiate(&mut store, &module).unwrap();
    instance_id.store(instance.id().as_u32(), Ordering::SeqCst);
    {
        let mut instance_ref = store.as_context_mut().0.instance_mut(instance.id());
        let tmemory = instance_ref
            .as_mut()
            .get_tmemory_mut(wasmtime_environ::TMemoryIndex::from_u32(0))
            .unwrap();
        tmemory.commit_range(60, &[0x10, 0x11, 0x12, 0x13]).unwrap();
        tmemory
            .commit_range(TMEMORY_GRANULE_SIZE, &[0x14, 0x15, 0x16, 0x17])
            .unwrap();
    }
    let store_and_read = instance
        .get_typed_func::<(), i64>(&mut store, "store_and_read")
        .unwrap();

    store
        .transaction_state_mut()
        .begin_with_region_runtime(&runtime)
        .unwrap();
    assert_eq!(
        store_and_read.call(&mut store, ()).unwrap() as u64,
        u64::from_le_bytes([0x10, 0x11, 0x11, 0x22, 0x33, 0x44, 0x16, 0x17])
    );
    store.transaction_state_mut().abort().unwrap();
}

#[test]
#[cfg(feature = "transaction-mvcc")]
fn mvcc_visibility_tmemory_size_controls_bounds_and_staged_growth() {
    use core::sync::atomic::{AtomicBool, AtomicU32, Ordering};

    let engine = crate::Engine::default();
    let module = transaction_test_module(
        &engine,
        r#"
            (module
              (import "host" "advance" (func $advance))
              (tmemory $m 1 3)
              (func (export "snapshot_oob") (result i32)
                (call $advance)
                (i32.tload $m (i32.const 65536)))
              (func (export "size_and_grow") (result i32 i32)
                (call $advance)
                (tmemory.size $m)
                (tmemory.grow $m (i32.const 1))))
        "#,
    );
    let runtime = TransactionRegionRuntime::new_for_test();
    let visibility = runtime.visibility_for_test();
    let instance_id = Arc::new(AtomicU32::new(u32::MAX));
    let host_instance_id = Arc::clone(&instance_id);
    let host_visibility = visibility.clone();
    let advanced = Arc::new(AtomicBool::new(false));
    let host_advanced = Arc::clone(&advanced);
    let mut store = crate::Store::new(&engine, ());
    store.set_transaction_region_runtime_for_test(runtime.clone());
    let mut linker = crate::Linker::new(&engine);
    linker
        .func_wrap(
            "host",
            "advance",
            move |caller: crate::Caller<'_, ()>| -> Result<()> {
                if host_advanced.swap(true, Ordering::SeqCst) {
                    return Ok(());
                }
                let owner = host_instance_id.load(Ordering::SeqCst);
                let commit = Arc::new(CommitRecord::pending());
                let mut prepare = host_visibility.runtime().begin_prepare(commit.clone())?;
                prepare.prepare_memory_size(
                    GranuleId::TMemorySize {
                        instance: Some(owner),
                        memory_index: 0,
                    },
                    || Ok(1),
                    2,
                )?;
                drop(prepare);
                commit.commit(1)?;
                caller
                    .store
                    .0
                    .instance_mut(InstanceId::from_u32(owner))
                    .get_tmemory_mut(wasmtime_environ::TMemoryIndex::from_u32(0))
                    .context("missing transactional memory sidecar")?
                    .grow_to_pages(2)?;
                Ok(())
            },
        )
        .unwrap();
    let instance = linker.instantiate(&mut store, &module).unwrap();
    instance_id.store(instance.id().as_u32(), Ordering::SeqCst);
    let snapshot_oob = instance
        .get_typed_func::<(), i32>(&mut store, "snapshot_oob")
        .unwrap();
    let size_and_grow = instance
        .get_typed_func::<(), (i32, i32)>(&mut store, "size_and_grow")
        .unwrap();

    store
        .transaction_state_mut()
        .begin_with_region_runtime(&runtime)
        .unwrap();
    assert!(snapshot_oob.call(&mut store, ()).is_err());
    if store.transaction_state().active_transaction().is_some() {
        store.transaction_state_mut().abort().unwrap();
    }
    store
        .transaction_state_mut()
        .begin_with_region_runtime(&runtime)
        .unwrap();
    assert_eq!(size_and_grow.call(&mut store, ()).unwrap(), (1, 1));
    assert_eq!(
        store
            .transaction_state()
            .staged_memory_size_owned(Some(instance.id()), 0),
        Some(2)
    );
    store.transaction_state_mut().abort().unwrap();
}

#[test]
#[cfg(feature = "transaction-mvcc")]
fn mvcc_visibility_tmemory_staged_growth_reads_zero_then_staged_overlay() {
    use core::sync::atomic::{AtomicU32, Ordering};

    let engine = crate::Engine::default();
    let module = transaction_test_module(
        &engine,
        r#"
            (module
              (import "host" "advance" (func $advance))
              (tmemory $m 1 2)
              (func (export "grow_read_write") (result i32 i32)
                (local $zero i32)
                (call $advance)
                (drop (tmemory.grow $m (i32.const 1)))
                (local.set $zero (i32.tload $m (i32.const 65536)))
                (i32.tstore $m (i32.const 65536) (i32.const 77))
                (local.get $zero)
                (i32.tload $m (i32.const 65536))))
        "#,
    );
    let runtime = TransactionRegionRuntime::new_for_test();
    let visibility = runtime.visibility_for_test();
    let instance_id = Arc::new(AtomicU32::new(u32::MAX));
    let host_instance_id = Arc::clone(&instance_id);
    let host_visibility = visibility.clone();
    let mut store = crate::Store::new(&engine, ());
    store.set_transaction_region_runtime_for_test(runtime.clone());
    let mut linker = crate::Linker::new(&engine);
    linker
        .func_wrap(
            "host",
            "advance",
            move |caller: crate::Caller<'_, ()>| -> Result<()> {
                let owner = host_instance_id.load(Ordering::SeqCst);
                let commit = Arc::new(CommitRecord::pending());
                let mut prepare = host_visibility.runtime().begin_prepare(commit.clone())?;
                prepare.prepare_memory_size(
                    GranuleId::TMemorySize {
                        instance: Some(owner),
                        memory_index: 0,
                    },
                    || Ok(1),
                    2,
                )?;
                drop(prepare);
                commit.commit(1)?;

                let mut instance = caller.store.0.instance_mut(InstanceId::from_u32(owner));
                let tmemory = instance
                    .as_mut()
                    .get_tmemory_mut(wasmtime_environ::TMemoryIndex::from_u32(0))
                    .context("missing transactional memory sidecar")?;
                tmemory.grow_to_pages(2)?;
                tmemory.commit_range(65536, &99_i32.to_le_bytes())?;
                Ok(())
            },
        )
        .unwrap();
    let instance = linker.instantiate(&mut store, &module).unwrap();
    instance_id.store(instance.id().as_u32(), Ordering::SeqCst);
    let grow_read_write = instance
        .get_typed_func::<(), (i32, i32)>(&mut store, "grow_read_write")
        .unwrap();

    store
        .transaction_state_mut()
        .begin_with_region_runtime(&runtime)
        .unwrap();
    assert_eq!(grow_read_write.call(&mut store, ()).unwrap(), (0, 77));
    store.transaction_state_mut().abort().unwrap();
}

