#[test]
fn shared_runtime_rejects_duplicate_persistent_object_reservation() {
    let runtime = TransactionRegionRuntime::new_for_test();
    let object = ObjectId { object_index: 41 };

    runtime
        .reserve_persistent_object_metadata(
            object,
            ObjectKind::Struct,
            TypeLayoutId::DEFAULT_STRUCT.get(),
        )
        .unwrap();
    runtime
        .reserve_persistent_object_metadata(
            object,
            ObjectKind::Struct,
            TypeLayoutId::DEFAULT_STRUCT.get(),
        )
        .unwrap();
    assert!(
        runtime
            .persistent_object_directory_entry(object)
            .unwrap()
            .is_none()
    );
    assert!(
        runtime
            .reserve_persistent_object_metadata(
                object,
                ObjectKind::Array,
                TypeLayoutId::DEFAULT_ARRAY.get(),
            )
            .is_err()
    );
    assert!(
        runtime
            .reserve_persistent_object_metadata(
                object,
                ObjectKind::Struct,
                TypeLayoutId::DEFAULT_ARRAY.get(),
            )
            .is_err()
    );
    assert!(
        runtime
            .install_persistent_object_directory_entries([PersistentObjectDirectoryEntry {
                object_id: object,
                kind: ObjectKind::Array,
                directory_version: 0,
                record_version: 1,
                type_layout_id: TypeLayoutId::DEFAULT_ARRAY.get(),
                runtime_type_index: None,
                record_source: None,
            }])
            .is_err()
    );
    let installed = runtime
        .install_persistent_object_directory_entries([PersistentObjectDirectoryEntry {
            object_id: object,
            kind: ObjectKind::Struct,
            directory_version: 0,
            record_version: 1,
            type_layout_id: TypeLayoutId::DEFAULT_STRUCT.get(),
            runtime_type_index: None,
            record_source: None,
        }])
        .unwrap();
    assert_eq!(installed.len(), 1);
    assert_eq!(
        runtime
            .persistent_object_directory_entry(object)
            .unwrap()
            .unwrap()
            .kind,
        ObjectKind::Struct
    );
}

#[test]
fn shared_object_directory_keeps_highest_record_version() {
    let runtime = TransactionRegionRuntime::default();
    let object = ObjectId { object_index: 11 };

    let installed = runtime
        .install_persistent_object_directory_entries([PersistentObjectDirectoryEntry {
            object_id: object,
            kind: ObjectKind::Struct,
            directory_version: 0,
            record_version: 2,
            type_layout_id: 1,
            runtime_type_index: None,
            record_source: None,
        }])
        .unwrap();
    assert_eq!(installed.len(), 1);
    let first_directory_version = installed[0].directory_version;

    runtime
        .install_persistent_object_directory_entries([PersistentObjectDirectoryEntry {
            object_id: object,
            kind: ObjectKind::Struct,
            directory_version: 0,
            record_version: 1,
            type_layout_id: 1,
            runtime_type_index: None,
            record_source: None,
        }])
        .unwrap();

    let equal_installed = runtime
        .install_persistent_object_directory_entries([PersistentObjectDirectoryEntry {
            object_id: object,
            kind: ObjectKind::Struct,
            directory_version: 0,
            record_version: 2,
            type_layout_id: 1,
            runtime_type_index: None,
            record_source: None,
        }])
        .unwrap();
    assert_eq!(equal_installed.len(), 1);
    assert_eq!(
        equal_installed[0].directory_version,
        first_directory_version
    );

    let entry = runtime
        .persistent_object_directory_entry(object)
        .unwrap()
        .unwrap();
    assert_eq!(entry.record_version, 2);
    assert_eq!(entry.directory_version, first_directory_version);
}

