#[cfg(all(unix, has_virtual_memory))]
#[test]
fn linear_memory_commit_logs_only_touched_shared_file_backed_granules() {
    clear_current_thread_transaction_for_test();

    let dir = tempfile::tempdir().unwrap();
    let tmemory_path = dir.path().join("tmemory.bin");
    let tx_log_path = dir.path().join("tx-log.bin");
    let runtime =
        crate::runtime::transaction::TransactionRegionRuntime::create_file_backed_for_test(
            &tmemory_path,
            &tx_log_path,
            64,
        )
        .unwrap();
    let mut tmemory = crate::runtime::vm::TMemory::new(
        TransactionConfig::with_file_backed_tmemory_path(tmemory_path).unwrap(),
        1,
        Some(1),
    )
    .unwrap();

    let granule0_addr = 8usize;
    let granule1_addr = TMEMORY_GRANULE_SIZE + 8;
    let granule2_addr = TMEMORY_GRANULE_SIZE * 2 + 8;
    tmemory
        .commit_range(granule0_addr, &[0x10, 0x11, 0x12, 0x13])
        .unwrap();
    tmemory
        .commit_range(granule1_addr, &[0x20, 0x21, 0x22, 0x23])
        .unwrap();
    tmemory
        .commit_range(granule2_addr, &[0x30, 0x31, 0x32, 0x33])
        .unwrap();

    let mut state = TransactionState::default();
    let shared = runtime
        .shared_file_backed_storage()
        .unwrap()
        .expect("shared file-backed storage config");
    state.open_shared_file_backed_durable_log(&shared).unwrap();
    state.begin_with_region_runtime(&runtime).unwrap();
    state
        .stage_tmemory_write_for_test(
            0,
            0,
            u64::try_from(granule0_addr).unwrap(),
            &[0xa0, 0xa1, 0xa2, 0xa3],
            &tmemory,
        )
        .unwrap();
    state
        .stage_tmemory_write_for_test(
            0,
            0,
            u64::try_from(granule2_addr).unwrap(),
            &[0xc0, 0xc1, 0xc2, 0xc3],
            &tmemory,
        )
        .unwrap();

    let (stream_id, _) = state.durable_publication_ids().unwrap();
    assert!(state.commit_tmemory_for_test(&mut tmemory).unwrap());

    let entries = state.durable_log_entries_for_test(stream_id);
    assert_eq!(entries.len(), 2);
    assert!(
        entries.iter().all(|entry| {
            entry.role().unwrap() == crate::runtime::vm::TxLogEntryRole::TMemoryUndo
        })
    );
    let staged_granule = vec![0; TMEMORY_GRANULE_SIZE];
    let expected_undo_logical_ids = BTreeSet::from([
        tmemory
            .prepare_tmemory_undo_record(Some(0), 0, 0, &staged_granule)
            .unwrap()
            .logical_id,
        tmemory
            .prepare_tmemory_undo_record(Some(0), 0, 2, &staged_granule)
            .unwrap()
            .logical_id,
    ]);
    let undo_logical_ids = entries
        .iter()
        .map(|entry| entry.logical_id)
        .collect::<BTreeSet<_>>();
    assert_eq!(undo_logical_ids, expected_undo_logical_ids);

    assert_eq!(
        tmemory
            .read_committed(granule0_addr..granule0_addr + 4)
            .unwrap(),
        vec![0xa0, 0xa1, 0xa2, 0xa3]
    );
    assert_eq!(
        tmemory
            .read_committed(granule1_addr..granule1_addr + 4)
            .unwrap(),
        vec![0x20, 0x21, 0x22, 0x23]
    );
    assert_eq!(
        tmemory
            .read_committed(granule2_addr..granule2_addr + 4)
            .unwrap(),
        vec![0xc0, 0xc1, 0xc2, 0xc3]
    );

    state.clear_active().unwrap();
    clear_current_thread_transaction_for_test();
}

#[test]
fn shared_region_runtime_detects_cross_thread_write_conflict() {
    use crate::runtime::transaction::{GranuleId, TransactionId};
    use std::sync::mpsc;
    use std::thread;

    let runtime = crate::runtime::transaction::TransactionRegionRuntime::new_for_test();
    let granule = GranuleId::TMemory {
        instance: None,
        memory_index: 0,
        granule_index: 7,
    };
    let (owned_tx, owned_rx) = mpsc::channel();
    let (attempted_tx, attempted_rx) = mpsc::channel();

    let first_runtime = runtime.clone();
    let first = thread::spawn(move || {
        first_runtime
            .acquire_granule_write_for_test(TransactionId::from_raw(1), granule, 0)
            .unwrap();
        owned_tx.send(()).unwrap();
        attempted_rx.recv().unwrap();
        first_runtime
            .release_transaction_for_test(TransactionId::from_raw(1))
            .unwrap();
    });

    owned_rx.recv().unwrap();
    let second_runtime = runtime.clone();
    let second = thread::spawn(move || {
        let result =
            second_runtime.acquire_granule_write_for_test(TransactionId::from_raw(2), granule, 0);
        attempted_tx.send(()).unwrap();
        if transaction_cc_is_ownerless_multiwriter() {
            result.is_ok()
        } else {
            result.is_err()
        }
    });

    assert!(second.join().unwrap());
    first.join().unwrap();
}

#[test]
fn shared_transaction_states_detect_cross_thread_write_conflict() {
    use crate::runtime::transaction::{GranuleId, TransactionState};
    use std::sync::mpsc;
    use std::thread;

    let runtime = crate::runtime::transaction::TransactionRegionRuntime::new_for_test();
    let granule = GranuleId::TGlobal {
        instance: Some(1),
        global_index: 7,
    };
    let (owned_tx, owned_rx) = mpsc::channel();
    let (attempted_tx, attempted_rx) = mpsc::channel();

    let first_runtime = runtime.clone();
    let first = thread::spawn(move || {
        let mut state = TransactionState::default();
        state.begin_with_region_runtime(&first_runtime).unwrap();
        state.acquire_granule_write(granule, 0).unwrap();
        owned_tx.send(()).unwrap();
        attempted_rx.recv().unwrap();
        state.abort().unwrap();
    });

    owned_rx.recv().unwrap();
    let second_runtime = runtime.clone();
    let second = thread::spawn(move || {
        let mut state = TransactionState::default();
        state.begin_with_region_runtime(&second_runtime).unwrap();
        let result = state.acquire_granule_write(granule, 0);
        attempted_tx.send(()).unwrap();
        if transaction_cc_is_ownerless_multiwriter() {
            if result.is_ok() {
                state.abort().unwrap();
                return true;
            }
            state.abort().unwrap();
            return false;
        }
        if result.is_err() {
            state.abort().unwrap();
            return true;
        }
        state.abort().unwrap();
        false
    });

    assert!(second.join().unwrap());
    first.join().unwrap();
}

#[test]
fn shared_region_runtime_disjoint_lock_acquisition_can_overlap_before_terminal_publication() {
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::{Arc, Barrier};
    use std::thread;

    clear_current_thread_transaction_for_test();

    let runtime = crate::runtime::transaction::TransactionRegionRuntime::new_for_test();
    let metadata_held = Arc::new(Barrier::new(2));
    let disjoint_attempted = Arc::new(Barrier::new(2));
    let progress = Arc::new(AtomicUsize::new(0));

    let first_runtime = runtime.clone();
    let first_metadata_held = metadata_held.clone();
    let first_disjoint_attempted = disjoint_attempted.clone();
    let first_progress = progress.clone();
    let first = thread::spawn(move || {
        clear_current_thread_transaction_for_test();

        let mut state = TransactionState::default();
        state.begin_with_region_runtime(&first_runtime).unwrap();
        state
            .acquire_granule_write(global_granule_id(None, 0), 0)
            .unwrap();
        first_progress.store(1, Ordering::SeqCst);

        first_runtime
            .with_root_object_metadata_lock_for_test(|| {
                first_progress.store(2, Ordering::SeqCst);
                first_metadata_held.wait();
                first_disjoint_attempted.wait();
                assert_eq!(first_progress.load(Ordering::SeqCst), 4);
                Ok(())
            })
            .unwrap();

        state.abort().unwrap();
        clear_current_thread_transaction_for_test();
    });

    let second_runtime = runtime.clone();
    let second_metadata_held = metadata_held;
    let second_disjoint_attempted = disjoint_attempted;
    let second_progress = progress.clone();
    let second = thread::spawn(move || {
        clear_current_thread_transaction_for_test();

        second_metadata_held.wait();

        let mut state = TransactionState::default();
        state.begin_with_region_runtime(&second_runtime).unwrap();
        second_progress.store(3, Ordering::SeqCst);

        let transaction = state.active_transaction_required().unwrap();
        let action = second_runtime
            .try_acquire_granule_write_for_test(transaction, global_granule_id(None, 1), 0)
            .unwrap();
        assert_eq!(action.aborted_transaction(), None);
        second_progress.store(4, Ordering::SeqCst);

        second_disjoint_attempted.wait();
        state.clear_active().unwrap();
        clear_current_thread_transaction_for_test();
    });

    first.join().unwrap();
    second.join().unwrap();

    assert_eq!(progress.load(Ordering::SeqCst), 4);

    clear_current_thread_transaction_for_test();
}

#[test]
fn shared_region_runtime_disjoint_pre_lp_publications_can_overlap() {
    use crate::runtime::transaction::persist::RecordingBackendEvent;
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::{Arc, Barrier};
    use std::thread;

    clear_current_thread_transaction_for_test();

    let runtime = crate::runtime::transaction::TransactionRegionRuntime::new_for_test();
    let metadata_held = Arc::new(Barrier::new(2));
    let both_published_before_lp = Arc::new(Barrier::new(2));
    let pre_lp_publication_count = Arc::new(AtomicUsize::new(0));

    let first_runtime = runtime.clone();
    let first_metadata_held = metadata_held.clone();
    let first_both_published_before_lp = both_published_before_lp.clone();
    let first_pre_lp_publication_count = pre_lp_publication_count.clone();
    let first = thread::spawn(move || {
        clear_current_thread_transaction_for_test();

        let (durable_log, events) = TxDurableLog::recording_backend_for_test();
        let mut state = TransactionState::default();
        state.durable_log = durable_log;
        let transaction = state.begin_with_region_runtime(&first_runtime).unwrap();
        let granule = GranuleId::TMemory {
            instance: None,
            memory_index: 0,
            granule_index: 0,
        };
        state.acquire_granule_write(granule, 0).unwrap();
        let stream_id = first_runtime
            .current_thread_log_segment_for_test()
            .unwrap()
            .stream_id();
        let txid = u32::try_from(transaction.as_raw()).unwrap();

        state.begin_terminal_commit().unwrap();
        let undo = PendingGranuleUndo::tmemory(0x1000_0000_0000_0000, 1, vec![0x11; 8]);
        let marker = state
            .publish_tmemory_undo_before_in_place_write(stream_id, txid, &undo)
            .unwrap();

        {
            let events = events.lock().unwrap();
            assert!(events.contains(&RecordingBackendEvent::AppendDataRecord(
                persist::DurableDataStream::TMemoryUndo,
            )));
            assert!(events.contains(&RecordingBackendEvent::AppendLogEntry(
                crate::runtime::vm::TxLogEntryRole::TMemoryUndo,
            )));
            assert!(
                !events
                    .iter()
                    .any(|event| matches!(event, RecordingBackendEvent::MarkLogEntryCommitted(_)))
            );
        }

        first_pre_lp_publication_count.fetch_add(1, Ordering::SeqCst);
        first_runtime
            .with_root_object_metadata_lock_for_test(|| {
                first_metadata_held.wait();
                first_both_published_before_lp.wait();
                assert_eq!(first_pre_lp_publication_count.load(Ordering::SeqCst), 2);
                Ok(())
            })
            .unwrap();

        state.publish_commit_lp(stream_id, txid, marker).unwrap();
        let events = events.lock().unwrap().clone();
        assert!(
            events.contains(&RecordingBackendEvent::MarkLogEntryCommitted(
                crate::runtime::vm::TxLogEntryRole::TMemoryUndo,
            ))
        );
        state.complete_commit().unwrap();
        clear_current_thread_transaction_for_test();

        (stream_id, txid, events)
    });

    let second_runtime = runtime;
    let second_metadata_held = metadata_held;
    let second_both_published_before_lp = both_published_before_lp;
    let second_pre_lp_publication_count = pre_lp_publication_count;
    let second = thread::spawn(move || {
        clear_current_thread_transaction_for_test();

        second_metadata_held.wait();

        let (durable_log, events) = TxDurableLog::recording_backend_for_test();
        let mut state = TransactionState::default();
        state.durable_log = durable_log;
        let transaction = state.begin_with_region_runtime(&second_runtime).unwrap();
        let granule = GranuleId::TMemory {
            instance: None,
            memory_index: 0,
            granule_index: 1,
        };
        state.acquire_granule_write(granule, 0).unwrap();
        let stream_id = second_runtime
            .current_thread_log_segment_for_test()
            .unwrap()
            .stream_id();
        let txid = u32::try_from(transaction.as_raw()).unwrap();

        state.begin_terminal_commit().unwrap();
        let undo = PendingGranuleUndo::tmemory(0x1000_0000_0000_0001, 1, vec![0x22; 8]);
        let marker = state
            .publish_tmemory_undo_before_in_place_write(stream_id, txid, &undo)
            .unwrap();

        {
            let events = events.lock().unwrap();
            assert!(events.contains(&RecordingBackendEvent::AppendDataRecord(
                persist::DurableDataStream::TMemoryUndo,
            )));
            assert!(events.contains(&RecordingBackendEvent::AppendLogEntry(
                crate::runtime::vm::TxLogEntryRole::TMemoryUndo,
            )));
            assert!(
                !events
                    .iter()
                    .any(|event| matches!(event, RecordingBackendEvent::MarkLogEntryCommitted(_)))
            );
        }

        second_pre_lp_publication_count.fetch_add(1, Ordering::SeqCst);
        second_both_published_before_lp.wait();
        assert_eq!(second_pre_lp_publication_count.load(Ordering::SeqCst), 2);

        state.publish_commit_lp(stream_id, txid, marker).unwrap();
        let events = events.lock().unwrap().clone();
        assert!(
            events.contains(&RecordingBackendEvent::MarkLogEntryCommitted(
                crate::runtime::vm::TxLogEntryRole::TMemoryUndo,
            ))
        );
        state.complete_commit().unwrap();
        clear_current_thread_transaction_for_test();

        (stream_id, txid, events)
    });

    let (first_stream_id, first_txid, first_events) = first.join().unwrap();
    let (second_stream_id, second_txid, second_events) = second.join().unwrap();

    assert_ne!(first_stream_id, first_txid);
    assert_ne!(second_stream_id, second_txid);
    assert_ne!(first_stream_id, second_stream_id);
    assert_eq!(
        first_events
            .iter()
            .filter(|event| matches!(
                event,
                RecordingBackendEvent::MarkLogEntryCommitted(
                    crate::runtime::vm::TxLogEntryRole::TMemoryUndo
                )
            ))
            .count(),
        1
    );
    assert_eq!(
        second_events
            .iter()
            .filter(|event| matches!(
                event,
                RecordingBackendEvent::MarkLogEntryCommitted(
                    crate::runtime::vm::TxLogEntryRole::TMemoryUndo
                )
            ))
            .count(),
        1
    );

    clear_current_thread_transaction_for_test();
}

