#[test]
#[cfg(feature = "transaction-cc-lockbased")]
fn shared_region_runtime_conflict_abort_before_terminal_commit_frees_active_allocations() {
    use std::sync::mpsc;
    use std::thread;

    let runtime = crate::runtime::transaction::TransactionRegionRuntime::new_for_test();
    let (owned_tx, owned_rx) = mpsc::channel();
    let (preempted_tx, preempted_rx) = mpsc::channel();

    let younger_runtime = runtime.clone();
    let younger = thread::spawn(move || {
        let mut objects = ObjectTable::default();
        let allocated = objects.allocate_struct(vec![ObjectValue::I32(99)]).unwrap();
        let mut state = TransactionState::default();
        state.shared_region_runtime = Some(younger_runtime);
        state
            .enter_transaction(TransactionId::from_raw(100_001))
            .unwrap();
        state.record_allocated_object(allocated).unwrap();
        state.stage_global(0, GlobalSnapshot::I32(100)).unwrap();
        owned_tx.send(()).unwrap();
        preempted_rx.recv().unwrap();

        let error = state
            .begin_terminal_commit_with_cleanup_for_test(&mut objects)
            .unwrap_err();
        assert!(error.to_string().contains("conflict-aborted"), "{error:?}");
        assert_eq!(state.active_transaction(), None);
        assert!(objects.kind(allocated).is_err());
    });

    owned_rx.recv().unwrap();
    let older_runtime = runtime.clone();
    let older = thread::spawn(move || {
        let mut state = TransactionState::default();
        state.shared_region_runtime = Some(older_runtime);
        state.enter_transaction(TransactionId::from_raw(1)).unwrap();
        state.stage_global(0, GlobalSnapshot::I32(200)).unwrap();
        preempted_tx.send(()).unwrap();
        state.abort().unwrap();
    });

    younger.join().unwrap();
    older.join().unwrap();
}

#[test]
#[cfg(feature = "transaction-cc-nowait-abort")]
fn shared_region_runtime_nowait_conflict_does_not_abort_existing_owner() {
    let runtime = crate::runtime::transaction::TransactionRegionRuntime::new_for_test();
    let owner = TransactionId::from_raw(100_001);
    let contender = TransactionId::from_raw(1);

    let mut owning_state = TransactionState::default();
    owning_state.shared_region_runtime = Some(runtime.clone());
    owning_state.enter_transaction(owner).unwrap();
    owning_state
        .stage_global(0, GlobalSnapshot::I32(100))
        .unwrap();
    owning_state.restore_transaction(None).unwrap();

    let mut contender_state = TransactionState::default();
    contender_state.shared_region_runtime = Some(runtime.clone());
    contender_state.enter_transaction(contender).unwrap();
    let error = contender_state
        .stage_global(0, GlobalSnapshot::I32(200))
        .unwrap_err();
    assert!(
        error.to_string().contains("transaction write conflict"),
        "{error:?}"
    );

    assert!(
        !runtime
            .take_conflict_aborted_transaction_for_test(owner)
            .unwrap()
    );
    contender_state.abort().unwrap();
    owning_state.restore_transaction(Some(owner)).unwrap();
    assert_eq!(
        owning_state.staged_global_owned(None, 0),
        Some(GlobalSnapshot::I32(100))
    );
    owning_state.abort().unwrap();
    assert_eq!(current_thread_transaction_for_test(), None);
}

#[test]
#[cfg(feature = "transaction-cc-wait-die")]
fn shared_runtime_wait_die_would_wait_does_not_conflict_abort_owner() {
    let runtime = TransactionRegionRuntime::new_for_test();
    let older = TransactionId::from_raw(1);
    let younger = TransactionId::from_raw(2);
    let granule = GranuleId::TMemory {
        instance: Some(1),
        memory_index: 0,
        granule_index: 7,
    };

    runtime
        .acquire_granule_write_for_test(younger, granule, 0)
        .unwrap();
    let action = runtime
        .acquire_granule_write_for_test(older, granule, 0)
        .unwrap();

    assert_eq!(
        action,
        super::concurrency::TransactionConflictAction::WouldWait(younger)
    );
    assert!(
        !runtime
            .take_conflict_aborted_transaction_for_test(younger)
            .unwrap()
    );
}

#[test]
fn shared_region_runtime_terminal_owner_cannot_be_preempted() {
    let runtime = crate::runtime::transaction::TransactionRegionRuntime::new_for_test();
    let owner = TransactionId::from_raw(100_001);
    let older = TransactionId::from_raw(1);
    let granule = global_granule_id(None, 0);

    runtime
        .acquire_granule_write_for_test(owner, granule, 0)
        .unwrap();
    runtime.begin_terminal_commit_for_test(owner).unwrap();

    if transaction_cc_is_ownerless_multiwriter() {
        let action = runtime
            .acquire_granule_write_for_test(older, granule, 0)
            .unwrap();
        assert_eq!(
            action,
            super::concurrency::TransactionConflictAction::Continue
        );
    } else {
        let error = runtime
            .acquire_granule_write_for_test(older, granule, 0)
            .unwrap_err();
        assert!(
            error.to_string().contains("transaction write conflict"),
            "{error:?}"
        );
    }
    assert!(
        !runtime
            .take_conflict_aborted_transaction_for_test(owner)
            .unwrap()
    );
}

