#[test]
fn transaction_object_tstruct_field_helpers_read_staged_payload_before_committed_record() {
    let mut objects = ObjectTable::default();
    let object = objects
        .allocate_struct(vec![ObjectValue::I32(1), ObjectValue::I64(2)])
        .unwrap();
    let mut state = TransactionState::default();

    state.begin().unwrap();
    state.acquire_object_write(&mut objects, object).unwrap();

    assert_eq!(
        state.read_struct_field(&mut objects, object, 0).unwrap(),
        ObjectValue::I32(1)
    );
    state
        .stage_struct_field(&mut objects, object, 0, ObjectValue::I32(9))
        .unwrap();

    assert_eq!(objects.version(object).unwrap(), 1);
    assert_eq!(
        objects.payload(object).unwrap(),
        ObjectPayload::Struct(vec![ObjectValue::I32(1), ObjectValue::I64(2)])
    );
    assert_eq!(
        state.read_struct_field(&mut objects, object, 0).unwrap(),
        ObjectValue::I32(9)
    );
    assert!(state.owns_object_write(object));

    assert!(state.commit_object_payloads(&mut objects).unwrap());
    state.complete_commit().unwrap();

    assert_eq!(
        objects.payload(object).unwrap(),
        ObjectPayload::Struct(vec![ObjectValue::I32(9), ObjectValue::I64(2)])
    );
    assert!(!state.owns_object_write(object));
}

#[test]
fn transaction_object_tstruct_field_abort_discards_staged_payload() {
    let mut objects = ObjectTable::default();
    let object = objects
        .allocate_struct(vec![ObjectValue::I32(1), ObjectValue::I32(2)])
        .unwrap();
    let mut state = TransactionState::default();

    state.begin().unwrap();
    state.acquire_object_write(&mut objects, object).unwrap();
    state
        .stage_struct_field(&mut objects, object, 1, ObjectValue::I32(7))
        .unwrap();
    assert_eq!(
        state.read_struct_field(&mut objects, object, 1).unwrap(),
        ObjectValue::I32(7)
    );

    state.abort().unwrap();

    assert_eq!(
        objects.payload(object).unwrap(),
        ObjectPayload::Struct(vec![ObjectValue::I32(1), ObjectValue::I32(2)])
    );
    assert!(!state.owns_object_write(object));
}

#[test]
fn transaction_object_abort_frees_objects_allocated_by_active_transaction() {
    let mut objects = ObjectTable::default();
    let mut state = TransactionState::default();

    state.begin().unwrap();
    let object = objects.allocate_struct(vec![ObjectValue::I32(1)]).unwrap();
    state.record_allocated_object(object).unwrap();
    assert_eq!(objects.live_count(), 1);

    state.abort_allocated_objects(&mut objects).unwrap();

    assert!(state.active_transaction().is_none());
    assert_eq!(objects.live_count(), 0);
    assert!(objects.kind(object).is_err());

    let reused = objects.allocate_array(vec![ObjectValue::I32(2)]).unwrap();
    assert_eq!(reused, object);
}

#[test]
fn transaction_object_commit_keeps_objects_allocated_by_active_transaction() {
    let mut objects = ObjectTable::default();
    let mut state = TransactionState::default();

    state.begin().unwrap();
    let object = objects.allocate_struct(vec![ObjectValue::I32(1)]).unwrap();
    state.record_allocated_object(object).unwrap();
    state.complete_commit().unwrap();

    assert_eq!(objects.live_count(), 1);
    assert_eq!(
        objects.payload(object).unwrap(),
        ObjectPayload::Struct(vec![ObjectValue::I32(1)])
    );

    state.begin().unwrap();
    state.abort_allocated_objects(&mut objects).unwrap();

    assert_eq!(objects.live_count(), 1);
    assert_eq!(
        objects.payload(object).unwrap(),
        ObjectPayload::Struct(vec![ObjectValue::I32(1)])
    );
}

#[test]
fn transaction_local_object_allocation_is_isolated_until_commit() {
    let mut objects = ObjectTable::default();
    let mut state = TransactionState::default();

    state.begin().unwrap();
    let local = state
        .allocate_transaction_local_struct(vec![ObjectValue::I32(1)], None)
        .unwrap();
    let handle = state
        .transaction_ref_handle_for_object_id_avoiding(&mut objects, local, |_| false)
        .unwrap();

    assert!(local.object_index >= (1u64 << 63));
    assert_eq!(objects.live_count(), 0);
    assert!(objects.kind(local).is_err());
    assert_eq!(
        state.known_object_id_for_transaction_ref_handle(&objects, handle),
        Some(local)
    );
    assert!(
        objects
            .known_object_id_for_transaction_ref_handle(handle)
            .is_none()
    );

    state
        .stage_struct_field(&mut objects, local, 0, ObjectValue::I32(9))
        .unwrap();
    assert_eq!(
        state.read_struct_field(&mut objects, local, 0).unwrap(),
        ObjectValue::I32(9)
    );
    assert_eq!(objects.live_count(), 0);

    assert!(!state.commit_object_payloads(&mut objects).unwrap());
    assert_eq!(objects.live_count(), 0);
    assert!(
        objects
            .known_object_id_for_transaction_ref_handle(handle)
            .is_none()
    );
    assert_eq!(
        state.known_object_id_for_transaction_ref_handle(&objects, handle),
        None
    );

    state.complete_commit().unwrap();
}

#[test]
fn transaction_local_commit_persists_only_root_reachable_graph() {
    let mut objects = ObjectTable::default();
    let mut state = TransactionState::default();

    state.begin().unwrap();
    let child = state
        .allocate_transaction_local_struct(vec![ObjectValue::I32(7)], None)
        .unwrap();
    let root = state
        .allocate_transaction_local_struct(
            vec![ObjectValue::Ref(Some(child)), ObjectValue::Ref(Some(child))],
            None,
        )
        .unwrap();
    let unreachable = state
        .allocate_transaction_local_struct(vec![ObjectValue::I32(99)], None)
        .unwrap();
    let child_handle = state
        .transaction_ref_handle_for_object_id_avoiding(&mut objects, child, |_| false)
        .unwrap();
    let root_handle = state
        .transaction_ref_handle_for_object_id_avoiding(&mut objects, root, |_| false)
        .unwrap();
    let unreachable_handle = state
        .transaction_ref_handle_for_object_id_avoiding(&mut objects, unreachable, |_| false)
        .unwrap();

    state
        .stage_global_owned(None, 0, GlobalSnapshot::GcRef(root_handle))
        .unwrap();

    assert!(
        state
            .promote_persistent_references_before_commit(&mut objects)
            .unwrap()
    );
    assert!(state.commit_object_payloads(&mut objects).unwrap());

    let promoted_child = objects
        .object_id_for_transaction_ref_handle(child_handle)
        .unwrap();
    let promoted_root = objects
        .object_id_for_transaction_ref_handle(root_handle)
        .unwrap();
    assert!(objects.is_persistent(promoted_child).unwrap());
    assert!(objects.is_persistent(promoted_root).unwrap());
    assert_eq!(objects.live_count(), 2);
    assert_eq!(
        objects.payload(promoted_child).unwrap(),
        ObjectPayload::Struct(vec![ObjectValue::I32(7)])
    );
    assert_eq!(
        objects.payload(promoted_root).unwrap(),
        ObjectPayload::Struct(vec![
            ObjectValue::Ref(Some(promoted_child)),
            ObjectValue::Ref(Some(promoted_child)),
        ])
    );
    assert_eq!(
        state.known_object_id_for_transaction_ref_handle(&objects, child_handle),
        Some(promoted_child)
    );
    assert_eq!(
        state.known_object_id_for_transaction_ref_handle(&objects, root_handle),
        Some(promoted_root)
    );
    assert_eq!(
        state.known_object_id_for_transaction_ref_handle(&objects, unreachable_handle),
        None
    );
    assert!(
        objects
            .known_object_id_for_transaction_ref_handle(unreachable_handle)
            .is_none()
    );

    let root_delta = state
        .staged_persistent_root_delta_for_test(&objects)
        .unwrap();
    assert_eq!(
        root_delta
            .roots
            .get(&PersistentRootKey::Global {
                instance: None,
                global_index: 0,
            })
            .cloned()
            .unwrap(),
        object_set([promoted_root])
    );
    state
        .complete_commit_with_persistent_root_delta_for_test(root_delta)
        .unwrap();
}

