fn synthetic_recovered_mapped_source_for_test() -> (
    crate::runtime::vm::block_region::SyntheticRecoveredWinnerSourceHandle,
    alloc::sync::Arc<dyn crate::runtime::vm::block_region::MappedRegionSource>,
) {
    let source = crate::runtime::vm::block_region::new_synthetic_recovered_winner_source_for_test();
    let mapped_source =
        crate::runtime::vm::block_region::synthetic_recovered_winner_source_for_test(&source);
    (source, mapped_source)
}

fn register_recovered_object_record_in_synthetic_source_for_test(
    source: &crate::runtime::vm::block_region::SyntheticRecoveredWinnerSourceHandle,
    object_id: u64,
    version: u32,
    kind: u16,
    type_layout_id: u32,
    record_bytes: &[u8],
) -> usize {
    let domain = match kind {
        value if value == ObjectKind::Struct as u16 => {
            crate::runtime::vm::PackedGranuleDomain::TStruct
        }
        value if value == ObjectKind::Array as u16 => {
            crate::runtime::vm::PackedGranuleDomain::TArray
        }
        _ => unreachable!("unsupported synthetic recovered object kind {kind}"),
    };
    let data_record = TMemory::encode_publication_data_record(
        crate::runtime::vm::pack_object_granule_id(domain, object_id).unwrap(),
        version,
        domain as u16,
        type_layout_id,
        record_bytes,
    )
    .unwrap();
    crate::runtime::vm::block_region::register_synthetic_recovered_winner_data_record_for_test(
        source,
        &data_record,
    )
}

fn copy_recovered_winners_from_view_into_synthetic_source_for_test(
    region: &crate::runtime::vm::block_region::BlockRegionBackendView<'_>,
    winners: &[crate::runtime::vm::RecoveredObjectWinner],
) -> (
    Vec<crate::runtime::vm::RecoveredObjectWinner>,
    alloc::sync::Arc<dyn crate::runtime::vm::block_region::MappedRegionSource>,
) {
    let (source, mapped_source) = synthetic_recovered_mapped_source_for_test();
    let winners = winners
        .iter()
        .cloned()
        .map(|mut winner| {
            let mut record_bytes = Vec::new();
            winner
                .with_view_record_bytes(region, &mut |bytes| {
                    record_bytes.extend_from_slice(bytes);
                    Ok(())
                })
                .unwrap();
            winner.data_record_offset =
                register_recovered_object_record_in_synthetic_source_for_test(
                    &source,
                    winner.object_id,
                    winner.version,
                    winner.kind,
                    winner.type_layout_id,
                    &record_bytes,
                );
            winner
        })
        .collect();
    (winners, mapped_source)
}

fn synthetic_recovered_winners_for_test(
    build: impl FnOnce(
        &crate::runtime::vm::block_region::SyntheticRecoveredWinnerSourceHandle,
    ) -> Vec<crate::runtime::vm::RecoveredObjectWinner>,
) -> (
    Vec<crate::runtime::vm::RecoveredObjectWinner>,
    alloc::sync::Arc<dyn crate::runtime::vm::block_region::MappedRegionSource>,
) {
    let (source, mapped_source) = synthetic_recovered_mapped_source_for_test();
    (build(&source), mapped_source)
}

fn append_committed_object_winner(
    region: &mut crate::runtime::vm::block_region::VMemoryBlockRegion,
    stream_id: u32,
    stream: crate::runtime::vm::block_region::StreamCursor,
    block_seq: u32,
    publication: &persist::PendingPublication,
) {
    let record = TMemory::encode_publication_data_record(
        publication.logical_id,
        publication.version,
        publication.kind,
        publication.type_layout_id,
        &publication.payload,
    )
    .unwrap();
    let location = region.append_data_record(stream, &record).unwrap();
    let log_block = region.alloc_log_block(stream_id, block_seq).unwrap();
    let entry = TMemory::publication_log_entry(
        publication.logical_id,
        publication.version,
        stream_id << 1,
        location.data_block,
        location.data_offset,
        0,
        true,
    )
    .unwrap();
    write_log_entry_for_recovery_test(region, log_block, entry);
}

fn write_log_entry_for_recovery_test(
    region: &mut crate::runtime::vm::block_region::VMemoryBlockRegion,
    start_block: u32,
    entry: crate::runtime::vm::TxLogEntry,
) {
    let mut header = region.log_block_header(start_block).unwrap();
    header.entry_count = 1;
    let block_offset =
        usize::try_from(start_block).unwrap() * crate::runtime::vm::block_region::BLOCK_SIZE;
    region.write(block_offset, &header.as_bytes()).unwrap();
    let offset = block_offset + header.as_bytes().len();
    region
        .write(offset, &encode_tx_log_entry_for_recovery_test(entry))
        .unwrap();
}

fn encode_tx_log_entry_for_recovery_test(entry: crate::runtime::vm::TxLogEntry) -> [u8; 32] {
    let mut bytes = [0u8; 32];
    bytes[0..8].copy_from_slice(&entry.logical_id.to_le_bytes());
    bytes[8..12].copy_from_slice(&entry.version.to_le_bytes());
    bytes[12..16].copy_from_slice(&entry.tx_meta.to_le_bytes());
    bytes[16..20].copy_from_slice(&entry.data_block.to_le_bytes());
    bytes[20..24].copy_from_slice(&entry.data_offset.to_le_bytes());
    bytes[24..28].copy_from_slice(&entry.crc32.to_le_bytes());
    bytes[28..32].copy_from_slice(&entry.entry_meta.to_le_bytes());
    bytes
}

