#[test]
#[cfg(all(
    not(feature = "transaction-mvcc"),
    not(feature = "transaction-cc-strict-2pl")
))]
fn optimistic_certification_disjoint_permits_coexist() -> Result<()> {
    let authority = Arc::new(OptimisticCertificationAuthority::default());
    let first = single_version_certification_granule_for_test(10);
    let second = single_version_certification_granule_for_test(11);
    let first_permit = authority.acquire(
        TransactionId::from_raw(1),
        &BTreeSet::from([first]),
        &BTreeSet::from([first]),
    )?;
    let second_permit = authority.acquire(
        TransactionId::from_raw(2),
        &BTreeSet::from([second]),
        &BTreeSet::from([second]),
    )?;
    assert_eq!(authority.lifecycle_counts_for_test()?, (2, 2));
    drop((first_permit, second_permit));
    assert_eq!(authority.lifecycle_counts_for_test()?, (2, 0));
    Ok(())
}

#[test]
#[cfg(all(
    not(feature = "transaction-mvcc"),
    not(feature = "transaction-cc-strict-2pl")
))]
fn optimistic_certification_write_skew_sets_block_atomically() -> Result<()> {
    use std::time::Duration;

    let authority = Arc::new(OptimisticCertificationAuthority::default());
    let a = single_version_certification_granule_for_test(20);
    let b = single_version_certification_granule_for_test(21);
    let first = authority.acquire(
        TransactionId::from_raw(1),
        &BTreeSet::from([a, b]),
        &BTreeSet::from([a]),
    )?;
    let waiting_authority = authority.clone();
    let waiter = std::thread::Builder::new()
        .name("optimistic-certification-write-skew".into())
        .spawn(move || {
            let _cleanup = clear_current_thread_transaction_on_drop_for_test();
            waiting_authority.acquire(
                TransactionId::from_raw(2),
                &BTreeSet::from([a, b]),
                &BTreeSet::from([b]),
            )
        })?;

    assert!(
        authority
            .wait_until_blocked_for_test(TransactionId::from_raw(2), Duration::from_secs(1))?
    );
    drop(first);
    let second = waiter
        .join()
        .map_err(|_| crate::format_err!("optimistic certification worker panicked"))??;
    assert_eq!(
        second.reservations_for_test(),
        &[
            (a, CertificationMode::Shared),
            (b, CertificationMode::Exclusive),
        ]
    );
    Ok(())
}

#[test]
#[cfg(all(
    feature = "transaction-cc-optimistic-validation",
    not(feature = "transaction-mvcc")
))]
fn optimistic_validation_single_version_keeps_execution_time_version_checks() {
    let transaction = TransactionId::from_raw(1);
    let read_granule = single_version_certification_granule_for_test(0);
    let write_granule = single_version_certification_granule_for_test(1);
    let mut read_policy = OptimisticValidation::default();
    read_policy
        .record_read(transaction, read_granule, 5)
        .unwrap();
    let read_error = read_policy
        .record_read(transaction, read_granule, 6)
        .unwrap_err();
    assert!(
        read_error
            .to_string()
            .contains("optimistic read version changed"),
        "{read_error:?}"
    );

    let mut write_policy = OptimisticValidation::default();
    write_policy
        .acquire_write(transaction, write_granule, 7)
        .unwrap();
    let write_error = write_policy
        .acquire_write(transaction, write_granule, 8)
        .unwrap_err();
    assert!(
        write_error
            .to_string()
            .contains("optimistic write version changed"),
        "{write_error:?}"
    );
}

